import sys

class Animal:
    def speak(self):
        raise NotImplementedError

class Lion(Animal):
    def speak(self):
        return "Roar"

class Elephant(Animal):
    def speak(self):
        return "Trumpet"

class Monkey(Animal):
    def speak(self):
        return "Ooh Ooh Aah Aah"

def solve() -> None:
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return
    try:
        n = int(data[0].strip())
    except:
        n = 0
    animals = []
    for i in range(1, min(len(data), n + 1)):
        animal_type = data[i].strip()
        if animal_type == "Lion":
            animals.append(Lion())
        elif animal_type == "Elephant":
            animals.append(Elephant())
        elif animal_type == "Monkey":
            animals.append(Monkey())
    out = [a.speak() for a in animals]
    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()
